import{_ as d,l as i,o as e,c as n,v as o,p as c,x as t,d as s,i as l,S as h}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"UTF-8 变长","description":"","frontmatter":{"title":"UTF-8 变长","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/utf8.md","filePath":"cs/utf8.md","lastUpdated":1789023840000}'),x={name:"cs/utf8.md"};function p(E,a,F,T,u,A){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="utf-8-变长" tabindex="-1">UTF-8 变长 <a class="header-anchor" href="#utf-8-变长" aria-label="Permalink to &quot;UTF-8 变长&quot;">​</a></h1><div class="epigraph"><p>ASCII 必须仍是单字节，其余码位用前缀声明长度；续字节以 $10$ 开头，既可自同步，又让非法序列无处躲。</p><footer>—— 据 RFC 3629；The Unicode Standard 整理</footer></div><p>上一课<a href="/cs/char-unicode">字符与 Unicode</a>钉死了：抽象字符先有码位，再选字节方案；并已点名 UTF-8 把 ASCII 嵌成子集。本课不重划 <code>U+10FFFF</code>，也不从「各国代码页史」另起。缺口是：变长的<strong>比特前缀</strong>还没有写成表。没有这张表，缓冲按字节切会切断序列，超长编码会把 <code>U+0000</code> 伪装成多字节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>码位是整数；文件与套接字只看见字节。固定 32 位会把 ASCII 撑成四倍，且与 Unix 字节流习惯冲突。缺口因此不是再编号一次，而是一套前缀：首字节的前导 \\(1\\) 的个数声明总长，续字节一律 <code>10xxxxxx</code>，合法码位不得用过长形式写出。</p><p>本课只钉 UTF-8。UTF-16 代理对上一课已警告宽度不是「一个字符」；本课不把它当默认交换格式。熵与分布还没有：变长省的是常见码位的<strong>字节数</strong>，不是 Shannon 信息量。</p><h3 id="自同步不是纠错" tabindex="-1">自同步不是纠错 <a class="header-anchor" href="#自同步不是纠错" aria-label="Permalink to &quot;自同步不是纠错&quot;">​</a></h3><p>从任意字节向后扫描，遇到非 <code>10</code> 开头的即可当作候选首字节。这能发现某些截断，不能纠正翻转——那是<a href="/cs/error-correcting-intuition">纠错码</a>的几何。把 UTF-8 前缀当成汉明码，后课 CRC 会没有位置。</p><p><span class="marginnote">RFC 3629 禁止超长编码，并把合法范围限制在 Unicode 码位。Pike 与 Thompson 的原始 UTF-8 设计目标之一就是：ASCII 字节在多字节流里仍只表示 ASCII。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>码位 \\(0\\)–\\(7\\mathrm{F}\\)：一字节 <code>0xxxxxxx</code>。\\(80\\)–\\(7\\mathrm{FF}\\)：<code>110xxxxx 10xxxxxx</code>。再往上三字节、四字节，首字节分别为 <code>1110xxxx</code>、<code>11110xxx</code>。译码时必须检查：续字节形态、码位落在对应范围、不落在代理区、不超过 <code>10FFFF</code>。失败则替换或报错，不得当 Latin-1 继续吃。</p>',11)),(e(),c(h,null,{default:t(()=>[l(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CP%5B%22%E7%A0%81%E4%BD%8D%22%5D%20--%3E%20PRE%5B%22%E5%89%8D%E7%BC%80%E5%A3%B0%E6%98%8E%E9%95%BF%E5%BA%A6%22%5D%0A%20%20PRE%20--%3E%20BYTES%5B%221%20%E8%87%B3%204%20%E5%AD%97%E8%8A%82%22%5D%0A%20%20BYTES%20--%3E%20REJ%5B%22%E6%8B%92%E7%BB%9D%E8%B6%85%E9%95%BF%E4%B8%8E%E6%88%AA%E6%96%AD%22%5D%0A%20%20REJ%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%AC%A6%E5%8F%B7%E4%B8%8A%E7%9A%84%E7%86%B5%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>相等：规范化后再比码位序列。按原始字节比，同一字符的非法超长与合法短形式会变成两个串——所以必须先拒绝超长。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了前缀，词法扫描可以按字节走并在字符边界停下。操作系统路径仍是字节；解释成字符时声明 UTF-8，则非法序列是数据错误，不是「少见汉字」。C 的 <code>char</code> 是字节，不是码位；宽字符类型若按码位索引，与 UTF-8 存储不是同一把尺子。后课信息量把字母表当随机变量的取值，默认这张表已经能写成字节。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 NFC/NFD、字素簇、emoji 序列。也不把压缩（Huffman）提前：变长是码位到字节的语法，不是按频率编的最优码。</p><p>后课默认：文本交换用 UTF-8；长度要声明是字节还是码位；非法与超长序列不是合法数据。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>UTF-8 用前缀变长，ASCII 单字节嵌入。</li><li>续字节 <code>10</code> 开头，可自同步；超长必须拒绝。</li><li>前缀能发现部分非法，不是纠错码。</li><li>出处：RFC 3629；The Unicode Standard。</li></ul>',8))])}const f=d(x,[["render",p]]);export{_ as __pageData,f as default};
